pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address currentOwner) public {
        // caller must not be the current owner to test the access control violation
        vm.assume(caller != currentOwner);
        // set the initial owner to currentOwner
        vm.prank(address(this));
        c.transferOwnership(currentOwner);
        // record the owner before the call
        address ownerBefore = c.owner();
        // simulate the caller (who is not the owner) attempting transferOwnership
        vm.prank(caller);
        // wrap in try/catch to gracefully handle potential reverts
        bool reverted;
        try c.transferOwnership(caller) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The invariant: if caller is not the current owner, the call MUST revert
        // i.e., when it doesn't revert, owner must not change, but we assert the revert behavior only.
        // Actually we assert a stronger property: for any caller, owner after the call is either the old owner
        // or the caller, but ONLY if the caller was already the owner.
        // Since we assume caller != currentOwner, the only acceptable outcome is a revert.
        assertTrue(reverted);
    }
}

