// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        // set initial owner to this test contract
        vm.prank(address(this));
        c.transferOwnership(address(this));
        // first transfer: transfer ownership to newOwner
        vm.prank(address(this));
        (bool ok1, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        // second transfer: attempt to transfer ownership again from this test contract
        // if c.owner() is still address(this), it will succeed; if bug set owner to address(0), it will revert
        vm.prank(address(this));
        (bool ok2, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        // assert: the second call must succeed (reference: original owner unchanged, bug: owner becomes 0, reverts)
        assertTrue(ok2);
    }
}

