pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address fuzzedNewOwner) public {
        // Ensure the caller is not the current owner (address(c) is the deployer of c, which is the test contract).
        vm.assume(fuzzedNewOwner != address(this));
        // The test contract is the current owner (C's constructor sets owner = deployer).
        // The fuzz parameter fuzzedNewOwner represents any new owner.
        // A random external actor (not owner) attempts to change ownership.
        vm.prank(address(0x1000));
        try c.transferOwnership(fuzzedNewOwner) {
            // If the call succeeds (no revert), then the new owner must be fuzzedNewOwner
            // according to the reference. But the reference will revert because address(0x1000) != owner.
            // The buggy version (no require) will execute the assignment.
            assertTrue(c.owner() == fuzzedNewOwner);
        } catch {
            // If the call reverts (reference behavior due to onlyOwner), the owner must remain unchanged.
            assertTrue(c.owner() == address(this));
        }
    }
}

