pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Set a non-zero owner to make the test meaningful
        vm.prank(address(0xBEEF));
        c.transferOwnership(address(0xBEEF));
    }
    function testFuzz_property(address sender, address newOwner) public {
        // Restrict sender to be different from the current owner to check access control
        vm.assume(sender != address(c.owner()));
        // Preclude the zero address as newOwner to avoid trivial zero-owner transfers confusing the rule
        vm.assume(newOwner != address(0));

        // Execute transferOwnership as the non-owner sender
        vm.prank(sender);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));

        // Rule: any non-owner invocation of transferOwnership MUST revert; anything else violates access control
        // The reference contract reverts (ok == false); the buggy contract succeeds for any caller.
        // Here we check that the original public entry is only callable by owner, i.e., it reverts for non-owner.
        assertTrue(!ok, "Non-owner should not be able to change owner");
    }
}

